function motionRange(o,start,end){if(!isAnimatedCharacter(o)||o.locked)throw Error('Choose an unlocked character.');if(!Number.isFinite(start)||!Number.isFinite(end)||start<clipStart(o)||end>clipEnd(o)+.001||end-start<.1||end-start>20)throw Error('Choose a range of 0.1 to 20 seconds inside the character clip.');if(motionTake||recording)throw Error('Finish the current recording first.')}
function captureMotionClip(o,{name='My motion',start=0,end=current().duration,region='all'}={}){motionRange(o,start,end);if(!['all','arms','legs','head'].includes(region))throw Error('Choose a body region.');const fields=(region==='all'?motionFields:Object.keys(bodyRegions[region].fields)).filter(f=>bodyFieldAvailable(o,f));if(!fields.length)throw Error('This rig has no controls for the selected region.');const count=Math.ceil((end-start)*15),frames=[];for(let i=0;i<=count;i++){const at=start+(end-start)*i/count,v=stateAt(o,at);frames.push({t:at-start,v:Object.fromEntries([...fields,'x','y','rotation'].map(f=>[f,v[f]]))})}const base=frames[0].v;for(const frame of frames)for(const field of Object.keys(frame.v))frame.v[field]-=base[field];return{id:uid(),version:1,name:name.trim().slice(0,80)||'My motion',duration:end-start,sourceHeight:o.height||250,fields,frames}}
function validMotionClip(c){return c&&c.version===1&&typeof c.id==='string'&&typeof c.name==='string'&&c.name.length<=80&&Number.isFinite(c.duration)&&c.duration>=.1&&c.duration<=20&&Number.isFinite(c.sourceHeight)&&c.sourceHeight>0&&c.sourceHeight<=2000&&Array.isArray(c.fields)&&c.fields.length>0&&new Set(c.fields).size===c.fields.length&&c.fields.every(f=>motionFields.includes(f))&&Array.isArray(c.frames)&&c.frames.length>=2&&c.frames.length<=302&&Math.abs(c.frames[0].t)<.001&&Math.abs(c.frames.at(-1).t-c.duration)<.001&&c.frames.every((k,i)=>Number.isFinite(k.t)&&k.t>=0&&k.t<=c.duration+.001&&(!i||k.t>c.frames[i-1].t)&&k.v&&Object.keys(k.v).length===c.fields.length+3&&[...c.fields,'x','y','rotation'].every(f=>Number.isFinite(k.v[f])&&Math.abs(k.v[f])<=10000))}
function mergeMotionValues(o,samples,fields,start,end){for(const [region,r]of Object.entries(bodyRegions)){const applicable=fields.filter(f=>Object.hasOwn(r.fields,f));if(!applicable.length)continue;const previous=o.bodyAnimation?.[region],track=bodyTrack(o,region);if(!previous){track.mode='replace';track.ease='linear'}for(const k of track.keys)if(k.t>=start-.001&&k.t<=end+.001)for(const f of applicable)delete k.v[f];track.keys=track.keys.filter(k=>Object.keys(k.v).length);for(const frame of samples)for(const f of applicable){let key=track.keys.find(k=>Math.abs(k.t-frame.t)<.001);if(!key){key={t:frame.t,v:{}};track.keys.push(key)}key.v[f]=clamp(frame.v[f],r.fields[f][1],r.fields[f][2])-(track.mode==='add'?poseBeforeBodyAnimation(o,frame.t)[f]:0)}track.keys.sort((a,b)=>a.t-b.t);if(track.keys.length>500)throw Error('This motion would exceed 500 keys in one body region. Use a shorter clip or fewer repeats.')}}
function buildMotionApplication(o,clip,{at=time,speed=1,strength=1,mirror=false,movement=false,repeat=1}={}){if(!validMotionClip(clip))throw Error('This motion clip is invalid.');if(![at,speed,strength,repeat].every(Number.isFinite)||speed<.25||speed>4||strength<0||strength>2||!Number.isInteger(repeat)||repeat<1||repeat>5)throw Error('Check the motion settings.');const duration=clip.duration/speed*repeat;motionRange(o,at,at+duration);const copy=structuredClone(o),base=stateAt(o,at),fields=clip.fields.filter(f=>bodyFieldAvailable(o,f)),map=f=>mirror?f.startsWith('left')?'right'+f.slice(4):f.startsWith('right')?'left'+f.slice(5):f:f,sign=f=>mirror&&f!=='blink'&&f!=='handOpen'&&f!=='browRaise'?-1:1,samples=[];if(!fields.length)throw Error('This rig has no compatible joint controls.');for(let n=0;n<repeat;n++)for(const frame of clip.frames){if(n&&frame.t===0)continue;const t=at+(n*clip.duration+frame.t)/speed,v={};for(const f of fields){const target=map(f);if(!bodyFieldAvailable(o,target))continue;v[target]=base[target]+frame.v[f]*strength*sign(f)}if(movement){const size=(o.height||250)/clip.sourceHeight;v.x=base.x+(frame.v.x+n*clip.frames.at(-1).v.x)*size*strength*(mirror?-1:1);v.y=base.y+(frame.v.y+n*clip.frames.at(-1).v.y)*size*strength;v.rotation=base.rotation+(frame.v.rotation+n*clip.frames.at(-1).v.rotation)*strength*(mirror?-1:1)}samples.push({t:Math.round(t*1000)/1000,v})}const appliedFields=[...new Set(samples.flatMap(k=>Object.keys(k.v)).filter(f=>motionFields.includes(f)))];mergeMotionValues(copy,samples,appliedFields,at,at+duration);if(movement){if(copy.motionPath?.enabled)throw Error('Disable the position path before applying motion with travel.');if(copy.actionBlocks?.some(b=>b.type==='walk'&&b.start<at+duration&&b.start+b.duration>at))throw Error('Apply the gesture without travel, or remove the overlapping walk first.');const old=copy.keys;copy.keys=[...old.filter(k=>k.t<at-.001||k.t>at+duration+.001),...samples.map(k=>({t:k.t,v:{...rawStateAt(o,k.t),x:k.v.x,y:k.v.y,rotation:k.v.rotation}}))].sort((a,b)=>a.t-b.t);copy.ease='linear';if(copy.keys.length>500)throw Error('This motion would exceed 500 main keys.')}if(!valid({...project,scenes:project.scenes.map(s=>s===current()?{...s,objects:s.objects.map(a=>a.id===o.id?copy:a)}:s)}))throw Error('The resulting motion has invalid timing or keys.');return copy}
function footForPose(o,side,v,at=time){const art=characterAtView(o,at);if(art.type==='character')return{key:side+'Foot',point:characterLocalToWorld(rigGeometry(v)[side+'Foot'],v,art.character)};const p=art.parts.find(p=>p.role===side+'Shin');if(!p||!art.parts.some(a=>a.id===p.parentId&&a.role===side+'Thigh'))throw Error('Connect the '+side+' thigh and shin first.');return{key:'part:'+p.id,point:puppetMatrices(art,v).matrices.get(p.id).transformPoint(puppetTip(p))}}
function buildMotionCleanup(o,{start=0,end=current().duration,smoothing=.5,strength=1,region='all',plant='none'}={}){motionRange(o,start,end);if(!Number.isFinite(smoothing)||smoothing<0||smoothing>1||!Number.isFinite(strength)||strength<0||strength>2||!['all','arms','legs','head','position'].includes(region)||!['none','left','right','both'].includes(plant))throw Error('Check the cleanup settings.');const copy=structuredClone(o),fields=region==='position'?['x','y','rotation']:Object.entries(bodyRegions).filter(([id])=>region==='all'||id===region).flatMap(([,r])=>Object.keys(r.fields)).filter(f=>bodyFieldAvailable(o,f)),count=Math.ceil((end-start)*15),source=[];if(region==='position'&&(o.motionPath?.enabled||o.actionBlocks?.some(b=>b.type==='walk'&&b.start<end&&b.start+b.duration>start)))throw Error('Active paths and walks control position. Clean joint motion or disable them first.');for(let i=0;i<=count;i++){const t=start+(end-start)*i/count;source.push({t:Math.round(t*1000)/1000,v:stateAt(o,t)})}const samples=source.map((frame,i)=>{const v={};for(const f of fields){let sum=0,weight=0;for(let j=Math.max(0,i-2);j<=Math.min(source.length-1,i+2);j++){const w=3-Math.abs(i-j);sum+=source[j].v[f]*w;weight+=w}const smoothed=i===0||i===count?frame.v[f]:frame.v[f]*(1-smoothing)+sum/weight*smoothing;v[f]=source[0].v[f]+(smoothed-source[0].v[f])*strength}return{t:frame.t,v}});if(region==='position'){copy.keys=[...copy.keys.filter(k=>k.t<start-.001||k.t>end+.001),...samples.map(k=>({t:k.t,v:{...rawStateAt(o,k.t),...k.v}}))].sort((a,b)=>a.t-b.t);copy.ease='linear';if(copy.keys.length>500)throw Error('Keep fewer than 500 position keys.')}else mergeMotionValues(copy,samples,fields,start,end);if(plant!=='none'){if(o.viewKeys?.some(k=>k.t>start&&k.t<end))throw Error('Split the foot-contact range at character view changes.');const sides=plant==='both'?['left','right']:[plant],initial=stateAt(copy,start),feet=sides.map(side=>({side,...footForPose(copy,side,initial,start)})),legSamples=[];for(const frame of source){let v=stateAt(copy,frame.t);for(const foot of feet)v=solveCharacterPin(characterAtView(copy,frame.t),foot.key,foot.point,v);for(const foot of feet){const actual=footForPose(copy,foot.side,v,frame.t).point;if(Math.hypot(actual.x-foot.point.x,actual.y-foot.point.y)>4)throw Error('The planted foot is out of reach. Use a shorter contact range or reduce body travel.')}legSamples.push({t:frame.t,v})}mergeMotionValues(copy,legSamples,Object.keys(bodyRegions.legs.fields).filter(f=>bodyFieldAvailable(copy,f)),start,end)}if(!valid({...project,scenes:project.scenes.map(s=>s===current()?{...s,objects:s.objects.map(a=>a.id===o.id?copy:a)}:s)}))throw Error('This cleanup would create invalid animation keys.');return copy}
function commitMotionCandidate(){const o=motionActor();if(!o||o.locked||!motionPreviewCandidate)return toast('Preview a change for an unlocked character first.');const before=motionPreviewCandidate.source;if(JSON.stringify(o)!==before){motionPreviewCandidate=null;return toast('The character changed. Preview again.')}Object.assign(o,motionPreviewCandidate.actor);motionPreviewCandidate=null;save();render();paintMotionWorkspace();toast('Motion applied. Undo restores the previous animation.')}
document.querySelector('#easyAnimationLibrary').insertAdjacentHTML('beforeend','<button id="libraryMotionClips">Motion clips & cleanup</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="motionLibraryDialog"><div class="tool-heading"><h2>Motion clips & cleanup</h2><button id="closeMotionLibrary">Done</button></div><div class="ease-two-col"><div><canvas id="motionLibraryPreview" width="640" height="360" aria-label="Motion preview"></canvas><label>Preview time<input id="motionLibraryTime" type="range" min="0" max="6" step="0.01"></label><p id="motionLibraryStatus" role="status" class="note"></p><label><input id="motionShowOriginal" type="checkbox"> Compare original</label><button id="applyMotionCandidate" class="primary">Apply previewed change</button></div><div><div class="rig-tools"><label>Start (s)<input id="motionRangeStart" type="number" min="0" max="60" step="0.1" value="0"></label><label>End (s)<input id="motionRangeEnd" type="number" min="0" max="60" step="0.1" value="2"></label></div><details open><summary>Reusable clips</summary><label>Save region<select id="motionClipCaptureRegion"><option value="arms">Hands & arms</option><option value="all">Whole body</option><option value="legs">Legs</option><option value="head">Head</option></select></label><label>Name<input id="motionClipName" maxlength="80" value="My gesture"></label><button id="saveMotionClip">Save range as motion</button><label class="button">Import motion<input id="importMotionClip" type="file" accept=".json" hidden></label><div id="motionClipList" class="ease-card-list"></div><div class="rig-tools"><label>Speed<input id="motionClipSpeed" type="number" min="0.25" max="4" step="0.1" value="1"></label><label>Strength<input id="motionClipStrength" type="number" min="0" max="2" step="0.1" value="1"></label><label>Repeats<input id="motionClipRepeat" type="number" min="1" max="5" value="1"></label></div><label><input id="motionClipMirror" type="checkbox"> Mirror gesture</label><label><input id="motionClipTravel" type="checkbox"> Include position movement</label><p class="note">Clips start at Start above, relative to the target’s current pose. Only compatible joints transfer. Automatic walking can continue under an arm gesture. Choose ranges up to 20 seconds.</p></details><details><summary>Clean up this character</summary><label>Region<select id="motionCleanupRegion"><option value="all">All joint keys</option><option value="arms">Hands & arms</option><option value="legs">Legs</option><option value="head">Head</option><option value="position">Position</option></select></label><label>Smoothing<input id="motionCleanupSmooth" type="range" min="0" max="100" value="60"></label><label>Movement strength<input id="motionCleanupStrength" type="range" min="0" max="200" value="100"></label><label>Hold a foot during this range<select id="motionCleanupPlant"><option value="none">No foot correction</option><option value="left">Left foot</option><option value="right">Right foot</option><option value="both">Both feet</option></select></label><button id="previewMotionCleanup">Preview cleanup</button><p class="note">Smoothing preserves range endpoints. Foot correction bakes connected leg poses over a short contact interval; unreachable contacts are rejected. Original keys stay intact until Apply.</p></details></div></div></dialog>`);
function paintMotionWorkspace(){const o=motionActor();if(!o)return;const candidate=motionPreviewCandidate&&!$('motionShowOriginal').checked?motionPreviewCandidate.actor:o,s=current(),original=s.objects;try{s.objects=original.map(a=>a.id===o.id?candidate:a);renderSceneFrame($('motionLibraryPreview').getContext('2d'),s,+$('motionLibraryTime').value)}finally{s.objects=original}$('applyMotionCandidate').disabled=!motionPreviewCandidate||o.locked;draw()}
function setMotionPreview(candidate){motionPreviewCandidate={actor:candidate,source:JSON.stringify(motionActor())};$('motionLibraryStatus').textContent='Preview ready. Scrub and compare with the original, then Apply.';paintMotionWorkspace()}
function motionUIOptions(){return{at:+$('motionRangeStart').value,speed:+$('motionClipSpeed').value,strength:+$('motionClipStrength').value,repeat:+$('motionClipRepeat').value,mirror:$('motionClipMirror').checked,movement:$('motionClipTravel').checked}}
function renderMotionClips(){const list=$('motionClipList');list.replaceChildren();for(const clip of savedMotionClips){const row=document.createElement('article');row.className='ease-entry';const name=document.createElement('span');name.textContent=clip.name+' · '+clip.duration.toFixed(1)+'s';row.append(name,storyButton('Preview',()=>{try{setMotionPreview(buildMotionApplication(motionActor(),clip,motionUIOptions()))}catch(e){toast(e.message)}}),storyButton('Save file',()=>download(new Blob([JSON.stringify(clip)],{type:'application/json'}),clip.name+'.motion.json')),storyButton('Remove',async()=>{try{const list=savedMotionClips.filter(c=>c.id!==clip.id);await workspacePut('motionClips',list);savedMotionClips=list;renderMotionClips()}catch{toast('Could not update the local motion library.')}}));list.append(row)}}
async function openMotionLibrary(o=object()){if(!isAnimatedCharacter(o)||o.locked)return toast('Select an unlocked character.');stop();motionWorkspaceActor=o.id;motionWorkspaceScene=current().id;motionPreviewCandidate=null;await motionClipsReady;$('motionRangeStart').value=+time.toFixed(2);$('motionRangeEnd').value=+Math.min(time+2,clipEnd(o)).toFixed(2);$('motionLibraryTime').max=current().duration;$('motionLibraryTime').value=time;$('motionShowOriginal').checked=false;$('motionLibraryStatus').textContent='Save a performed gesture, preview a reusable clip or clean up existing motion.';renderMotionClips();$('motionLibraryDialog').showModal();await preloadProductionAssets(current());paintMotionWorkspace()}
$('libraryMotionClips').onclick=()=>openMotionLibrary();$('closeMotionLibrary').onclick=()=>$('motionLibraryDialog').close();$('motionLibraryDialog').addEventListener('close',()=>{motionPreviewCandidate=null});$('motionLibraryTime').oninput=paintMotionWorkspace;$('motionShowOriginal').onchange=paintMotionWorkspace;$('applyMotionCandidate').onclick=commitMotionCandidate;
$('saveMotionClip').onclick=async()=>{try{if(savedMotionClips.length>=30)throw Error('Keep up to 30 saved motions. Export a motion file before removing one.');const clip=captureMotionClip(motionActor(),{name:$('motionClipName').value,region:$('motionClipCaptureRegion').value,start:+$('motionRangeStart').value,end:+$('motionRangeEnd').value}),list=[...savedMotionClips,clip];await workspacePut('motionClips',list);savedMotionClips=list;renderMotionClips();toast('Motion saved locally. Export its file to use it on another PC.')}catch(e){toast(e.message)}};
$('importMotionClip').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>1e6)throw Error('Choose a motion file smaller than 1 MB.');const clip=JSON.parse(await file.text());if(!validMotionClip(clip))throw Error('This is not a valid motion clip.');if(savedMotionClips.length>=30)throw Error('Keep up to 30 saved motions.');clip.id=uid();const list=[...savedMotionClips,clip];await workspacePut('motionClips',list);savedMotionClips=list;renderMotionClips()}catch(e){toast(e.message)}};
$('previewMotionCleanup').onclick=()=>{try{setMotionPreview(buildMotionCleanup(motionActor(),{start:+$('motionRangeStart').value,end:+$('motionRangeEnd').value,smoothing:+$('motionCleanupSmooth').value/100,strength:+$('motionCleanupStrength').value/100,region:$('motionCleanupRegion').value,plant:$('motionCleanupPlant').value}))}catch(e){toast(e.message)}};
const motionClipsReady=workspaceValue('motionClips').then(list=>{savedMotionClips=Array.isArray(list)?list.filter(validMotionClip).slice(0,30):[];motionLibraryReady=true}).catch(()=>{motionLibraryReady=true});
const controlsBeforeMotionLibrary=renderControls;renderControls=function(){controlsBeforeMotionLibrary();if(!isAnimatedCharacter(object()))return;const b=storyButton('Motion clips & cleanup',()=>openMotionLibrary());b.id='openMotionLibrary';b.disabled=!!object().locked;$('openBodyAnimation')?.after(b)};
